const CNL_LANGUAGE_PATH = 'data/seed/cnl-language-{language}.lino';
const TOKEN = /\.\.\.|…|\p{Script=Han}|[0-9]+(?:\.[0-9]+)?|[\p{L}\p{M}\p{N}]+(?:['-][\p{L}\p{M}\p{N}]+)*/gu;
